function createMenu(){show('Tỉnh dậy sau Nguyệt Toái',`<div class="prologue"><div><small>CHƯƠNG MỞ ĐẦU / NGÔI MỘ Ở TỊCH HÔI LÂM</small><h1>Một mảnh trăng trong lồng ngực.</h1><p>Ba trăm năm sau đêm Nguyệt Toái, ngươi mở mắt trong một ngôi mộ không tên. Tro giữ ký ức. Muối giữ lời thề. Mỗi sức mạnh đều đòi một cái giá.</p><div class="row">${btn('Lưu / tiếp tục hành trình','saves')}<a class="button" href="concepts.html" target="_blank">Xưởng concept ↗</a></div></div>${sprite(choice.starter)}</div><div class="row"><label>Tên lữ khách <input id="name" value="Vô Danh" maxlength="24"></label><label>Chế độ <select id="hardcore"><option value="no">Hành trình thường</option><option value="yes">Khắc Nghiệt · hết nến xóa ô lưu này</option></select></label></div><h3>1 · Huyết thống</h3><select id="create-race">${D.races.map(r=>`<option value="${r.id}" ${r.id===choice.race?'selected':''} ${r.locked&&!meta.races.includes(r.id)?'disabled':''}>${r.name}${r.locked&&!meta.races.includes(r.id)?' · Chưa mở khóa':''}</option>`).join('')}</select><div id="race-preview" class="lore"></div><h3>2 · Lớp nhân vật</h3><select id="create-class">${D.classes.filter(c=>!c.hidden).map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><div id="class-preview" class="lore"></div><h3>3 · Sinh linh sẽ giữ lời hứa cùng ngươi</h3><div class="grid">${[...D.progression.starters,...(meta.endings.length?[D.progression.secretStarter]:[])].map(id=>{const m=by('monsters',id);return `<article class="card ${id===choice.starter?'selected':''}">${sprite(id)}<h3>${m.name}</h3><p>${m.englishName} · ${m.types.join(' / ')}</p><p>${esc(m.appearanceAndBehavior)}</p>${btn('Chọn '+m.name,'starter',id)}</article>`;}).join('')}</div><p class="page-note">Tiềm lực starter tối thiểu B. Chủng tộc khóa sẽ dùng được ở lượt chơi mới sau khi hoàn thành nhiệm vụ mở khóa. Các lựa chọn cốt truyện được lưu lâu dài.</p>${btn('LẬP KHẾ HỒN · BƯỚC RA KHỎI MỘ','start','',false,'primary')}`,'create');const preview=()=>{$('race-preview').textContent=by('races',$('create-race').value).playableRules;$('class-preview').textContent=by('classes',$('create-class').value).playstyle;};$('create-race').onchange=preview;$('create-class').onchange=preview;preview();}
 function start(){const race=choice.race,cls=choice.cls;if(by('races',race).locked&&!meta.races.includes(race))return;S=R.newState(creation.name,race,cls,choice.starter,!!$('hardcore')?.checked,meta.cycles);heroMove=null;moveMarker=null;activeSlot='auto';B=null;resetNpcRuntime();resetNpcRuntime(S.mapId);S.hero.statPoints+=by('races',race).freeStatPoints;close();save();log('Mảnh Trăng thức tỉnh. Nguyệt Thực Giáo đã nhận ra ánh sáng của ngươi.');rivalMenu(true);}

