 if(action==='battle-speed'&&B&&S){S.settings.battleSpeed=(S.settings.battleSpeed||1)>=2?1:2;battleUI();return;}
 if(action==='battle-tactic'&&B){const [uid,skill]=id.split('|');if(B.acted||String(B.waitingUid)!==uid)return;if(B.loadouts[uid]?.includes(skill)){B.tactics[uid]=skill;B.activeUid=uid;turn('skill:'+skill);}return;}
 if(action==='loadout-menu'&&!B&&S){loadoutMenu(id||'hero');return;}
 if(B&&!['turn','battle','weakness-menu','capture-menu','battle-items','switch-menu','auto','battle-panel','battle-tactic'].includes(action))return;
 if(!S&&!['start','starter','new','saves','load-slot'].includes(action))return;
  if(action==='start'){start();return;}if(action==='starter'){choice.starter=id;creationStep=2;createMenu(2);return;}
   if(action==='new'){B=null;S=null;heroMove=null;moveMarker=null;resetNpcRuntime();creation={name:'Vô Danh',hardcore:false,skipPrologue:false};creationStep=0;leaveTitle();createMenu(0);return;}if(action==='load-slot'){const raw=store.get('vtn4-slot-'+id);if(raw)load(raw,id);return;}if(action==='saves'){savesMenu();return;}
 if(action==='journal'){journal();const ids=new Set();for(const el of document.querySelectorAll('#content [data-act="quest-investigate"],#content [data-act="quest-resolve"]')){const qid=el.dataset.id?.split(':')[0];if(!qid||ids.has(qid)||!by('quests',qid))continue;ids.add(qid);el.insertAdjacentHTML('afterend',btn('Tự tìm đường','quest-navigate',qid));}return;}
