 if(action==='city-pass'){if(id==='talk'&&R.heroStats(S).CHA<14||id==='pay'&&h.gold<100)return;if(id==='pay')h.gold-=100;if(id==='sneak')h.corruption=R.clamp(h.corruption+4,0,100);S.flags.cityPass=true;travel('region_06',true);return;}
  if(action==='move'){move(id);return;}if(action==='interact'){interact();return;}if(action==='travel'){travel(id);return;}if(action==='abyss-boss'){abyssBoss();return;}if(action==='abyss-linh-chu'){abyssLinhChu();return;}if(action==='abyss-memory'){abyssMemory({memoryIndex:Number(id)});return;}if(action==='turn'){turn(id);return;}if(action==='weakness-menu'){battleSub('weakness');return;}if(action==='capture-menu'){battleSub('capture');return;}if(action==='battle-items'){battleSub('items');return;}if(action==='switch-menu'){battleSub('switch');return;}if(action==='auto'){if(!B||B.mode!=='wild'||B.enemies[B.index].human||combatSpecies(B.enemies[B.index]).tierIndex>2)return;B.auto=!B.auto;if(B.auto)turn('attack');else battleUI();return;}
 if(action==='monster'){monsterDetail(id);return;}if(action==='race'){raceDetail(id);return;}if(action==='card'&&mon){captureCard(mon);return;}
 if(action==='leader'){leader(id);return;}if(action==='boss'){bossFight(id);return;}if(action==='boss-resolve'){finishBoss(id);return;}if(action==='npc'){npcMenu(id);return;}if(action==='npc-choice'){npcChoice(id);return;}if(action==='npc-clue'){const n=by('npcs',id);if(!S.clues.includes(n.mapId))S.clues.push(n.mapId);S.quests[n.questId]??={stage:'investigated'};npcMenu(id);save();return;}
