 if(action==='npc-duel'){const n=by('npcs',id),reg=by('regions',n.mapId),pool=D.monsters.filter(m=>m.regionId===reg.id&&m.tierIndex<6);beginBattle('duel',[R.instantiate(pool[0].id,Math.max(reg.recommendedLevel[1],h.level))],id);return;}
 if(action==='recruit'){const n=by('npcs',id);if(S.factions[n.factionId]<5||S.companions.length)return;S.companions.push(id);close();toast(n.name+' sẽ trợ giúp trong trận kế tiếp.');save();return;}
 if(action==='growth'){growthMenu(id);return;}if(action==='growth-apply'){growthApply(id);return;}
 if(action==='clue'){clue(id);return;}if(action==='puzzle'){solvePuzzle(id);return;}if(action==='quest-investigate'){const q=by('quests',id);if(!q||by('maps',S.mapId).regionId!==q.regionId){toast('Cần tới đúng vùng để đọc dấu vết.');return;}S.quests[id]??={stage:'investigated'};if(!S.discoveredWeaknesses.includes(q.speciesId))S.discoveredWeaknesses.push(q.speciesId);save();journal();return;}
