  function p10aAction(name,label,hint,act,id='',disabled=false){return `<button class="battle-command-button ${name==='skills'&&B?.panel==='skills'?'is-selected':''}" data-act="${act}" data-id="${esc(id)}" ${disabled?'disabled':''}>${p10aIcon(name)}<span>${label}</span><small>${hint}</small></button>`;}
  function p10aSkillPanel(uid){const ids=B.loadouts[uid]||[],targets=B.enemies.map((m,i)=>`<button data-act="battle-target" data-id="${i}" class="${B.index===i?'is-selected':''} ${m.hp<=0?'is-fainted':''}" ${m.hp<=0||B.acted?'disabled':''}>${esc(enemyName(m))} · ${Math.max(0,m.hp)} HP</button>`).join('');return `<div class="battle-panel-head"><div><small>LƯỢT RA CHIÊU</small><strong>${esc(uid==='hero'?S.hero.name:monName(g.VTNLoadouts.actor(S,uid)))}</strong></div><button class="battle-back-button" data-act="battle-option" data-id="root">Quay lại</button></div><div class="battle-targets" aria-label="Chọn mục tiêu">${targets}</div><div class="battle-skill-grid four-skills">${Array.from({length:4},(_,i)=>p10aSkillCard(ids[i]||null,uid,i)).join('')}<button class="battle-skill battle-skill-card battle-basic-strike" data-act="turn" data-id="attack" ${B.acted?'disabled':''}><span class="battle-skill-top"><b>0 MP</b></span><strong>Đòn thường</strong><small>Không tốn MP · ${uid==='hero'?'vũ khí':'khế thú'} ra đòn</small>${effectivenessMarkup({type:null},B.enemies[B.index])}</button></div>`;}
  const p10aInfoCell=(i,inner)=>`<div class="battle-item-cell">${inner}<button type="button" class="battle-info-button" data-act="battle-item-info" data-id="${esc(i.id)}" aria-label="Xem chi tiết ${esc(i.name)}" title="Xem chi tiết">i</button></div>`;
  function p10aItemInfoPanel(){const id=B.infoItem,d=itemCodex?.describe(id),it=by('items',id),h=S.hero,from=B.infoFrom==='capture'?'capture':'items';if(!d||!it)return `<div class="battle-panel-head"><div><small>VẬT PHẨM</small><strong>Không có thông tin</strong></div><button class="battle-back-button" data-act="battle-option" data-id="${from}">Quay lại</button></div>`;const own=h.bag[id]||0,isCap=it.kind==='capture',act=isCap?'capture:'+id:'item:'+id,e=B.enemies[B.index],chance=isCap&&e&&!e.human?Math.round(R.catchChance(S,e,it,B.weak>0)*100):null,canUse=own>0&&!B.locks.includes('items')&&!B.acted&&(!isCap||(B.mode==='wild'&&!(e?.captureLocked)));return `<div class="battle-panel-head"><div><small>${esc(d.kindLabel||'VẬT PHẨM')}</small><strong>${esc(d.title)} · còn ${own}</strong></div><button class="battle-back-button" data-act="battle-option" data-id="${from}">Quay lại</button></div><div class="battle-item-info"><div class="battle-item-info-icon">${itemSlot(id,d.title)}</div><div><p>${esc(d.summary||it.desc||'')}</p>${chance!==null?`<p><b>Tỉ lệ thu phục lúc này: ${chance}%</b></p>`:''}${(d.effects||[]).length?`<ul>${d.effects.filter(Boolean).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</div></div><div class="row">${btn(isCap?'Dùng phong ấn này':'Dùng vật phẩm','turn',act,!canUse)}</div>`;}
  function p10aHelpPanel(){S.flags.battleHelpSeen=true;return `<div class="battle-panel-head"><div><small>HƯỚNG DẪN</small><strong>Cách chiến đấu</strong></div><button class="battle-back-button" data-act="battle-option" data-id="root">Đã hiểu</button></div><div class="battle-help">${g.VTNTutorial?.battleHtml()||''}</div>`;}
  function p10aExitPanel(){return `<div class="battle-panel-head"><div><small>THOÁT</small><strong>Về menu chính?</strong></div><button class="battle-back-button" data-act="battle-option" data-id="settings">Quay lại</button></div><p>Trận đấu này sẽ bị bỏ. Lần sau chơi tiếp, bạn trở lại ngay trước khi vào trận.</p><div class="row">${btn('Thoát về menu chính','exit-confirm')}${btn('Tiếp tục trận','battle-option','root')}</div>`;}
  function p10aItemPanel(){const e=B.enemies[B.index],h=S.hero,locked=!!e.captureLocked,refusal=locked?R.captureRefusal:R.captureBlockReason(S,e);return `<div class="battle-panel-head"><div><small>KHẾ HỒN</small><strong>Lập khế ước với sinh linh</strong></div><button class="battle-back-button" data-act="battle-option" data-id="root">Quay lại</button></div>${refusal?`<p class="danger">${esc(refusal)}</p>`:''}<div class="battle-item-grid battle-item-grid-p10a">${D.items.filter(i=>i.kind==='capture'&&(i.id!=='nguyet_tam_an'||B.overlordId||e.speciesId==='M-200'||B.finalBoss)).map(i=>p10aInfoCell(i,itemButton(i.id,`${i.name} · ${h.bag[i.id]||0} · ${Math.round(R.catchChance(S,e,i,B.weak>0)*100)}%`,'turn','capture:'+i.id,locked||!(h.bag[i.id]>0)||B.locks.includes('items')))).join('')}</div>${p10aAction('overflow','Nói chuyện','Giữ sinh linh','turn','talk')}</div>`;}
