  function p10aSwitchPanel(){return `<div class="battle-panel-head"><div><small>ĐỔI VỊ TRÍ</small><strong>Đưa một khế thú lên sân</strong></div><button class="battle-back-button" data-act="battle-option" data-id="root">Quay lại</button></div><div class="battle-switch-grid">${S.party.map((m,i)=>`<button class="battle-switch-card" data-act="turn" data-id="switch:${i}" ${i<2||m.hp<=0?'disabled':''}>${sprite(m.speciesId,m.formId,m.variant,false,54,m.uid,m.look)}<span>${esc(monName(m))}</span><small>Cấp ${m.level} · ${m.hp} HP</small></button>`).join('')}</div>`;}
  function p10aOverflowPanel(){return `<div class="battle-panel-head"><div><small>THÊM LỰA CHỌN</small><strong>Những lời nói không thành tiếng</strong></div><button class="battle-back-button" data-act="battle-option" data-id="root">Quay lại</button></div><div class="battle-overflow-actions">${p10aAction('overflow','Nói chuyện','Đọc phản ứng của đối thủ','turn','talk')}${(()=>{const can=['wild','bandit'].includes(B.mode)||!!S.admin?.enabled;return p10aAction('overflow','Bỏ chạy','Rời khỏi giao tranh',can?'turn':'battle-option',can?'flee':'root',!can);})()}${p10aAction('overflow','Quan sát','Ghi điểm yếu','turn','observe')}${p10aAction('overflow','Khắc chế','Dùng bộ khảo sát: '+(S.hero.bag.fieldkit||0),'turn','weak',!(S.hero.bag.fieldkit>0)||!S.discoveredWeaknesses.includes(B.enemies[B.index]?.speciesId))}</div>`;}
  function p10aSettingsPanel(){return `<div class="battle-panel-head"><div><small>CÀI ĐẶT TRẬN</small><strong>Nhịp điệu của giao tranh</strong></div><button class="battle-back-button" data-act="battle-option" data-id="root">Quay lại</button></div><div class="battle-settings-copy"><p>Tốc độ trận: ${S.settings.battleSpeed} · Âm lượng: ${Math.round(S.settings.volume*100)}%</p><p class="small">Cài đặt đầy đủ vẫn được giữ trong menu Cài Đặt ngoài giao tranh.</p></div><div class="row">${btn('Hướng dẫn chiến đấu','battle-help')}${btn('Thoát về menu chính','battle-exit')}</div>`;}
  function p10aBattleConsole(){const uid=B.activeUid||'hero',panel=B.panel||'root';let inside=panel==='skills'||panel==='fight'?p10aSkillPanel(uid):panel==='capture'?p10aItemPanel():panel==='items'?p10aInventoryPanel():panel==='switch'?p10aSwitchPanel():panel==='overflow'?p10aOverflowPanel():panel==='settings'?p10aSettingsPanel():panel==='iteminfo'?p10aItemInfoPanel():panel==='help'?p10aHelpPanel():panel==='exit'?p10aExitPanel():`<div class="battle-console-main"><div class="battle-turn-hint">${B.acted?esc(B.actingId?(B.actingId==='enemy'?enemyName(B.enemies[B.index]):B.actingId==='hero'?S.hero.name:enemyName([...S.party,...B.enemies].find(m=>String(m.uid)===String(B.actingId))||{human:true,name:S.hero.name}))+' đang ra đòn…':'Đang xử lý lượt…'):'Lượt của <b>'+esc(uid==='hero'?S.hero.name:monName(g.VTNLoadouts.actor(S,uid)))+'</b> · chọn hành động'+p10aPendingNote()}</div><div class="battle-command-row">${p10aAction('attack','Tấn công','Chọn đòn','battle-option','skills',!g.VTNLoadouts.actor(S,uid)||g.VTNLoadouts.actor(S,uid).hp<=0||!!B.acted)}${p10aAction('capture','Khế hồn','Thu phục sinh linh','battle-option','capture',uid!=='hero'||(B.mode!=='wild'&&!B.overlordId&&!B.finalBoss)||B.enemies[B.index].human||!!B.acted)}${p10aAction('items','Vật phẩm','Hồi phục · giải trạng thái','battle-option','items',uid!=='hero'||!!B.acted)}${p10aAction('switch','Đổi vị trí','Đưa quái lên sân','battle-option','switch',uid!=='hero'||S.party.length<3||!!B.acted)}${p10aAction('guard','Phòng thủ','Giảm sát thương','turn','guard',!!B.acted)}${p10aAction('overflow','Thêm','Nói chuyện · Bỏ chạy','battle-option','overflow',uid!=='hero'||!!B.acted)}</div></div>`;return `<div class="battle-console">${inside}</div>`;}
  function p10aBattleUI(){if(!B)return;const enemy=B.enemies[B.index],region=by('maps',S.mapId)?.regionId,order=p10aOrder(),moon=g.VTN_EMBLEMS?.moon?.[Number(S.moon)%8]||'',party=[p10aPartyCard(S.hero,true),...S.party.slice(0,B.fieldCount??2).map((m,i)=>p10aPartyCard(m,false,i))],enemySummary=B.enemies.map(m=>{const sp=combatSpecies(m);return `<article class="battle-enemy-card" aria-hidden="true">${m.human?'':heartTag(m.heart)}${typeTags(sp.types)}${tierBadge(D.tiers[sp.tierIndex])}</article>`;}).join('');show('Giao tranh · '+enemyName(enemy),`<div class="battle-shell battle-desk"><header class="battle-topbar"><div class="battle-round-plate"><img src="${esc(moon)}" alt="Pha trăng" width="28" height="28"><span>Vòng ${String(Math.max(1,B.turn)).padStart(2,'0')}</span></div><div class="battle-turn-strip" aria-label="Thứ tự lượt">${order.map((actor,index)=>`<span class="battle-turn-diamond ${index===0?'is-current':''} ${B.actingId&&String(actor.uid)===String(B.actingId==='enemy'?B.enemies[B.index].uid:B.actingId)?'is-acting':''} ${actor.kind==='enemy'?'is-enemy':''}" data-order-uid="${esc(actor.uid)}">${p10aPortrait(actor)}${index===0?'<i aria-hidden="true"></i>':''}</span>`).join('')}</div><button class="battle-speed-button ${(S.settings.battleSpeed||1)>=2?'is-fast':''}" data-act="battle-speed" aria-label="Tốc độ trận">${(S.settings.battleSpeed||1)>=2?'Nhanh ×2':'Nhanh ×1'}</button><button class="battle-help-button" data-act="battle-help" aria-label="Hướng dẫn chiến đấu" title="Hướng dẫn chiến đấu">?</button><button class="battle-settings-button" data-act="battle-settings" aria-label="Cài đặt trận">${p10aIcon('settings')}<span>Cài đặt</span></button></header><div class="battle-stage-wrap" data-region="${esc(region||'region_01')}"></div>${enemySummary}<div class="battle-bottom"><section class="battle-party-panel"><div class="battle-section-kicker">ĐỘI HÌNH · ${S.party.slice(0,B.fieldCount??2).length+1}</div>${party.join('')}</section><section class="battle-command-dock ${B.acted?'is-busy':''}">${p10aBattleConsole()}</section><section class="battle-log-panel"><div class="battle-section-kicker">NHẬT KÝ</div><div class="battle-log-list" aria-live="polite">${B.logs.slice(-30).map(l=>`<p>${esc(l)}</p>`).join('')||'<p class="is-empty">Chọn một hành động. Ưu tiên theo SPD.</p>'}</div></section></div></div>`,'battle');const logList=document.querySelector('.battle-log-list');if(logList)logList.scrollTop=logList.scrollHeight;}
  function p10aSkillDetail(id){const sk=by('skills',id);if(!sk)return '<p class="small">Chưa trang bị.</p>';return `<p class="loadout-skill-detail">${typeTags([sk.type])} · ${sk.mpCost} MP · Uy lực ${sk.power}</p><p class="loadout-skill-description">${esc(stripEnglishNames(sk.description||''))}</p>`;}
  const p10aLoadoutTarget={};
  function p10aLoadoutMenu(uid='hero'){
    const L=g.VTNLoadouts,a=L.actor(S,uid);if(!a)return;L.snapshot(S);const available=L.available(S,uid),slots=L.equipped(S,uid),name=uid==='hero'?S.hero.name:monName(a);p10aLoadoutTarget[uid]=Number.isInteger(p10aLoadoutTarget[uid])?p10aLoadoutTarget[uid]:0;
    show('Kỹ năng · '+name,`<div class="loadout-heading"><div class="screen-tabs"><span class="is-active">Kỹ năng</span><button data-act="${uid==='hero'?'hero':'party'}">${uid==='hero'?'Nhân vật':'Đội hình'}</button></div><h2>Bốn kỹ năng mang vào trận</h2><p>Học nhiều kỹ năng, chọn đúng bốn kỹ năng chủ động. Chọn một ô rồi chọn kỹ năng đã học để đặt hoặc đổi vị trí.</p></div><div class="loadout-members"><button class="is-active" data-act="loadout-menu" data-id="hero">${esc(S.hero.name)}</button>${S.party.map(m=>`<button data-act="loadout-menu" data-id="${esc(m.uid)}">${esc(monName(m))}</button>`).join('')}</div><section class="loadout-slots-p10a"><div class="loadout-slots-title"><span>Ô đã trang bị</span><small>Đang chọn ô ${p10aLoadoutTarget[uid]+1}</small></div><div class="loadout-slot-grid">${Array.from({length:4},(_,i)=>{const id=slots[i],sk=by('skills',id);return `<button class="loadout-slot-card ${p10aLoadoutTarget[uid]===i?'is-selected':''}" data-act="loadout-slot" data-loadout-slot="${i}" data-id="${esc(uid)}|${i}"><span class="loadout-slot-number">${i+1}</span><strong>${sk?esc(stripEnglishNames(sk.name)):'Trống'}</strong>${sk?p10aSkillDetail(id):'<small>Chọn một kỹ năng bên dưới</small>'}</button>`;}).join('')}</div></section><section class="loadout-learned"><div class="loadout-slots-title"><span>Đã học · ${available.length}</span><small>Nhấn để đặt vào ô đang chọn</small></div><div class="loadout-learned-grid">${available.map(id=>{const sk=by('skills',id),slot=slots.indexOf(id);return `<button class="loadout-learned-card ${slot>=0?'is-equipped':''}" data-act="loadout-pick" data-id="${esc(uid)}|${esc(id)}"><span>${typeTags([sk.type])}</span><strong>${esc(stripEnglishNames(sk.name))}</strong><small>${slot>=0?'Ô '+(slot+1)+' · ':''}${sk.mpCost} MP · Uy lực ${sk.power}</small><p>${esc(stripEnglishNames(sk.description||''))}</p></button>`;}).join('')||'<p class="small">Chưa có kỹ năng chủ động nào.</p>'}</div></section><div class="row"><button data-act="party">Đội hình</button><button data-act="hero">Nhân vật</button><button data-act="close">Trở về phiêu lưu</button></div>`,'loadouts');
  }
  const p10aBaseBattleUI=battleUI,p10aBaseLoadoutMenu=loadoutMenu,p10aBasePartyMenu=partyMenu,p10aBaseHeroMenu=heroMenu,p10aBaseMonsterDetail=monsterDetail,p10aNativeAct=act;
  battleUI=p10aBattleUI;loadoutMenu=p10aLoadoutMenu;
  partyMenu=function(){p10aBasePartyMenu();const members=[...S.party,...S.storage];document.querySelectorAll('#content .card.collectible').forEach((card,index)=>{const m=members[index];if(m&&!card.querySelector('.party-skill-button'))card.insertAdjacentHTML('beforeend',`<div class="row party-skill-button">${btn('Kỹ năng','loadout-menu',String(m.uid))}</div>`);});};
  heroMenu=function(){p10aBaseHeroMenu();const intro=document.querySelector('#content .intro');if(intro&&!intro.querySelector('.character-skill-tab'))intro.insertAdjacentHTML('afterbegin',`<div class="screen-tabs character-skill-tab"><span class="is-active">Nhân vật</span>${btn('Kỹ năng','loadout-menu','hero')}</div>`);const flat=document.querySelector('#content .stats');if(flat){const st=R.heroStats(S),surface=document.createElement('section');surface.className='hero-radar-layout';surface.innerHTML=`${radarMarkup(st,{key:'hero-panel',title:'Chỉ số nhân vật',label:'Bát giác chỉ số',scale:'6—16 · số vượt thang có dấu +',min:6,max:16,note:'Bảng ẩn bên dưới vẫn đọc số đầy đủ.'})}<div class="stat-points-panel"><span class="preview-label">Phân bổ điểm</span>${statChips(st)}<div class="stat-point-actions">${creationStats.map(k=>btn(`${k} +1`,'stat',k,S.hero.statPoints<=0)).join('')}</div></div>`;flat.replaceWith(surface);g.VTNStatRadar?.mount(surface);}};
  monsterDetail=function(id){p10aBaseMonsterDetail(id);const m=[...S.party,...S.storage].find(v=>v.speciesId===id);const card=document.querySelector('#content .collectible');if(m&&card&&!card.querySelector('.monster-skill-tab'))card.insertAdjacentHTML('beforeend',`<div class="row monster-skill-tab">${btn('Kỹ năng','loadout-menu',String(m.uid))}</div>`);const species=by('monsters',id),flat=document.querySelector('#content .stats');if(species&&flat){const surface=document.createElement('section');surface.className='monster-radar-layout';surface.innerHTML=`${radarMarkup(species.baseStats,{key:'monster-'+id,title:`${species.name} · chỉ số`,label:'Bát giác chỉ số',scale:`cùng bậc · 0—${monsterRadarMax(species)}`,kind:'monster',min:0,max:monsterRadarMax(species),note:'Thang đo so với toàn bộ loài cùng bậc.'})}<div class="monster-stat-summary">${statChips(species.baseStats)}</div>`;flat.replaceWith(surface);g.VTNStatRadar?.mount(surface);}};
  function exitMenu(){if(!S)return;if(B){B.panel='exit';battleUI();return;}show('Thoát về menu chính',`<div class="intro"><h2>Về menu chính?</h2><p>Tiến trình của bạn đã được tự động lưu. Bạn có thể quay lại bằng <b>Tiếp tục</b> ở menu chính.</p></div>${btn('Lưu và thoát về menu','exit-confirm')}${btn('Ở lại chơi tiếp','close')}`);}
  function exitConfirm(){if(!S)return;if(!B)save();adventure?.cancelRoute(true);B=null;heroMove=null;moveMarker=null;document.getElementById('overlay')?.classList.remove('open');document.getElementById('story-overlay')?.classList.remove('is-active');navReset();titleMenu();}
  act=function(action,id=''){
    if(action==='exit-menu'){exitMenu();return;}
    if(action==='exit-confirm'){exitConfirm();return;}
    if(action==='tutorial'){if(B)return;show('Hướng dẫn tân thủ',g.VTNTutorial.html(Number(id)||0),'guide');return;}
    if(action==='tutorial-skip'){S.flags.tutorialOffered=true;save();close();return;}
    if(action==='battle-target'&&B){const index=Number(id);if(!B.acted&&Number.isInteger(index)&&B.enemies[index]?.hp>0){B.index=index;battleUI();}return;}
    if(action==='battle-settings'&&B){B.panel='settings';battleUI();return;}
    if(action==='battle-help'&&B){B.panel=B.panel==='help'?'root':'help';battleUI();return;}
    if(action==='battle-item-info'&&B){B.infoItem=id;B.infoFrom=B.panel==='capture'?'capture':'items';B.panel='iteminfo';battleUI();return;}
    if(action==='battle-exit'&&B){B.panel='exit';battleUI();return;}
    if(action==='battle-option'&&B){
      if(id==='root'){B.panel='root';battleUI();return;}
      if(id==='skills'||id==='capture'||id==='items'||id==='switch'||id==='overflow'){B.panel=id;B.activeUid=B.activeUid||'hero';battleUI();return;}
      if(id.startsWith('actor|')){if(B.acted)return;const uid=id.slice(6);if(!p10aPickUnit(uid)){toast('Không chọn được thành viên này.');return;}return;}
    }
    if(action==='loadout-slot'&&!B){const [uid,slot]=id.split('|');p10aLoadoutTarget[uid]=Number(slot);p10aLoadoutMenu(uid);return;}
    if(action==='loadout-pick'&&!B){const [uid,skill]=id.split('|');const slot=p10aLoadoutTarget[uid]??0;if(g.VTNLoadouts.set(S,uid,slot,skill)){save();p10aLoadoutMenu(uid);}return;}
    if(action==='loadout-replace'&&!B){const [skill,slot]=id.split('|');p10aNativeAct('learn',skill);if(S.hero.learned.includes(skill)){g.VTNLoadouts.set(S,'hero',Number(slot),skill);save();p10aLoadoutMenu('hero');}return;}
    if(action==='loadout-skip'&&!B){p10aNativeAct('learn',id);return;}
    if(action==='learn'&&!B){const cls=by('classes',S.hero.classId),sk=by('skills',id),L=g.VTNLoadouts,full=L.equipped(S,'hero').every(Boolean);if(sk&&cls?.skillIds.includes(id)&&!S.hero.learned.includes(id)&&full&&S.hero.level>=sk.level&&S.hero.skillPoints>0){show('Kỹ năng mới · '+stripEnglishNames(sk.name),`<div class="new-skill-prompt"><h2>Đã đủ bốn ô kỹ năng</h2><p>${esc(stripEnglishNames(sk.description||''))}</p><div class="loadout-replace-grid">${L.equipped(S,'hero').map((slot,i)=>{const old=by('skills',slot);return `<button data-act="loadout-replace" data-id="${esc(id)}|${i}"><strong>Đổi ô ${i+1}</strong><span>${esc(stripEnglishNames(old?.name||'Trống'))}</span></button>`;}).join('')}</div>${btn('Học nhưng để dự bị','loadout-skip',id)}${btn('Quay lại','hero')}</div>`,'loadouts');return;}
    }
    return p10aNativeAct(action,id);
  };
  if(g.VTNGame)g.VTNGame.act=act;
  manageUI=g.VTNManage.create({R,D,state:()=>S,show,esc,sprite,itemSlot,button:btn,typeTags,tierBadge,plain:stripEnglishNames,toast,save,hud,canBack:navCanBack});g.VTNGame.manage=manageUI;
  itemCodex=g.VTNItemCodex.create({R,D,state:()=>S,show,esc,itemSlot,button:btn,canBack:navCanBack,save,hud,toast});g.VTNGame.itemCodex=itemCodex;
  adventure=g.VTNAdventure.create({R,D,state:()=>S,battle:()=>B,show,close,save,hud,toast,sprite,monster:id=>monsterDetail(id),grid:id=>grid(by('maps',id)),points:id=>points(by('maps',id)),movement:()=>heroMove,stopMovement:()=>{heroMove=null;moveMarker=null;},move:moveToTile,interact,beginBattle,teleport:id=>{if(!S||B)return false;const target=by('maps',id);if(!target)return false;heroMove=null;moveMarker=null;adventure?.cancelRoute(true);if(!S.visited.includes(id))S.visited.push(id);const ok=storyMap(id);if(ok===false)return false;close();save();return true;},routeLabel:text=>{const el=$('route-status');if(el)el.textContent=text;const stop=document.querySelector('[data-act="route-stop"]');if(stop)stop.hidden=!text;}});
  atlas=()=>adventure.atlas();partyMenu=()=>adventure.storage();
  g.VTNGame.adventure=adventure;g.VTNGame.beginBattle=beginBattle;
  const adminButton=document.createElement('button');adminButton.dataset.act='admin';adminButton.innerHTML='<span>Quản trị</span>';adminButton.title='Bảng quản trị · Ctrl Shift A';$('nav').appendChild(adminButton);{const chip=document.createElement('button');chip.className='admin-chip';chip.type='button';chip.addEventListener('click',e=>{e.stopPropagation();if(!S||B)return;S.admin??={};if(!S.admin.enabled)act('admin-toggle');act('admin');});chip.title='Bảng quản trị · Ctrl Shift A';chip.innerHTML='<b>QUẢN TRỊ</b>';const head=document.querySelector('#game-ui>header');if(head)head.appendChild(chip);}
  setInterval(()=>{if(!S||B||g.VTN_TEST)return;if(document.body.classList.contains('title-mode')||S.flags.tutorialOffered||(S.wins||0)>=2)return;if(document.getElementById('overlay')?.classList.contains('open')||document.querySelector('#story-overlay.is-active')||g.VTNStory?.isActive?.())return;S.flags.tutorialOffered=true;show('Chào mừng đến Vực Tàn Nguyệt',`<div class="intro"><h2>Bạn mới chơi?</h2><p>Hướng dẫn ngắn giải thích cách di chuyển, thu phục khế thú, chiến đấu (có cả cách chọn lượt và dùng vật phẩm) và quản lý đội hình. Bạn có thể mở lại bất cứ lúc nào bằng nút <b>Hướng dẫn</b> ở thanh phía trên.</p></div>${btn('Xem hướng dẫn','tutorial')}${btn('Để sau','tutorial-skip')}`);save();},2500);
